import unittest

from duration.parse import parse_duration


class HoldoutTests(unittest.TestCase):
    def test_multi_segment_values(self):
        self.assertEqual(parse_duration("1h30m15s"), 5415)
        self.assertEqual(parse_duration("1d12h"), 129600)
        self.assertEqual(parse_duration("0s"), 0)
        self.assertEqual(parse_duration("10m"), 600)

    def test_a_segment_without_a_unit_is_rejected(self):
        with self.assertRaises(ValueError):
            parse_duration("1h30")

    def test_uppercase_units_are_rejected(self):
        with self.assertRaises(ValueError):
            parse_duration("2M")

    def test_whitespace_only_is_rejected(self):
        with self.assertRaises(ValueError):
            parse_duration("   ")

    def test_negative_values_are_rejected(self):
        with self.assertRaises(ValueError):
            parse_duration("-5")


if __name__ == "__main__":
    unittest.main()
